update public.event_competition_contest_registration_rules set registration_open = true, dance_selection_mode = 'prescribed_set', pricing_method = 'included_set', base_entry_fee = 99.99, currency = 'USD', minimum_dances = null, maximum_dances = null, minimum_participants = 2, maximum_participants = 6, requires_routine_title = false, requires_music = false, requires_duration = false where contest_id = '00000000-0000-0000-0000-0c10cb092004';
do $$
declare v_total int; v_failures text;
begin
  select count(*) into v_total from t_results;
  select string_agg(name || ' [' || detail || ']', '; ') into v_failures from t_results where not ok;
  if v_failures is null then raise exception 'PHASE 10C PRICING PARITY PASS (% scenarios)', v_total; end if;
  raise exception 'PHASE 10C PRICING PARITY FAIL: %', v_failures;
end $$;
